const prev = $('دریافت متن فارسی').first().json;
const m = $('deep_rules').first().json;
const text = prev.text ?? '';
const prompt =
  'متن فارسی زیر را سطر به سطر با تک‌تک بندهای این چک‌لیست ویراستاری کن. '
  + 'هر بندی که به متن می‌خورد اعمال کن؛ معنا را عوض نکن؛ چیزی کم یا اضافه نکن. '
  + 'فقط متن نهایی ویراسته را برگردان، بدون هیچ توضیحی.\n\n'
  + `چک‌لیست (${m.rules_count} قاعده):\n${m.checklist}\n\nمتن:\n${text}`;
return [{ json: { prompt } }];

const edited = $input.first().json.output ?? $input.first().json.text ?? '';
const m = $('deep_rules').first().json;
const prompt =
  'این چک‌لیست ویراستاری را بگیر و متن ویراسته را بند به بند با آن بسنج. '
  + 'هر بندی که هنوز رعایت نشده، دقیق بنویس کجای متن و چه ایرادی. '
  + 'خروجی فقط JSON معتبر، بدون هیچ متن اضافه:\n'
  + '{"issues": ["ایراد ۱: ..."], "clean": false}\n'
  + 'اگر هیچ ایرادی نیست: {"issues": [], "clean": true}\n\n'
  + `چک‌لیست:\n${m.checklist}\n\nمتن ویراسته:\n${edited}`;
return [{ json: { prompt, edited } }];

const raw = $input.first().json.output ?? '';
let clean = true, issues = [];
try {
  const m = raw.match(/\{[\s\S]*\}/);
  if (m) { const o = JSON.parse(m[0]);
    issues = Array.isArray(o.issues) ? o.issues : [];
    clean = o.clean === true && issues.length === 0;
  }
} catch (e) { clean = false; issues = ['خروجی بازبین JSON نبود؛ بازبینی دستی لازم است.']; }
return [{ json: { clean, issues } }];

const a = $input.first().json;
const edited = a.edited ?? '';
const m = $('deep_rules').first().json;
const items = (a.issues ?? []).map((s, i) => `${i+1}. ${s}`).join('
');
const prompt =
  'این متن یک بار ویراسته شده ولی بازبین هنوز این ایرادها را گزارش کرده:
'
  + items + '

فقط همین ایرادها را اصلاح کن؛ بقیهٔ متن را دست نزن. '
  + 'فقط متن نهایی را برگردان، بدون هیچ توضیحی.

'
  + `چک‌لیست:
${m.checklist}

متن:
${edited}`;
return [{ json: { prompt } }];

